parameters.jsCode:
// ---- Parse webhook payload (array-safe) ----
const webhookPayload = Array.isArray($json) ? $json[0] : $json;
const body = webhookPayload.body || {};

// ---- Extract basic contact info ----
const fullName = body.name || '';
const email = (body.email || '').toLowerCase().trim();

// ---- Name helpers ----
function splitName(fullName) {
  const parts = String(fullName).trim().split(/\s+/);
  return {
    first: parts[0] || '',
    last: parts.slice(1).join(' ') || '',
  };
}

const { first, last } = splitName(fullName);

// ---- Chiron / Astrology Data ----
const chironReport = {
  birthDate: body.birthDate || '',
  birthTime: body.birthTime || null,
  birthLocation: body.birthLocation || '',
  birthCoordinates: body.birthCoordinates || [],
  chironSign: body.chironSign || '',
  chironDegree: body.chironDegree || null,
  chironHouse: body.chironHouse || null,
  shadowId: body.shadowId || '',
  aiReport: body.aiReport || '',
  timestamp: body.timestamp || '',
};

// ---- Build GHL contact payload ----
const contactData = {
  body_locationId: 'KQwViSotgXlhDFQY6Xfg', // your GHL location ID
  body_firstName: first,
  body_lastName: last,
  body_email: email,

  body_tags: [
    'Chiron_Report_Completed',
    chironReport.chironSign ? `Chiron_${chironReport.chironSign}` : null,
    chironReport.chironHouse ? `Chiron_${chironReport.chironHouse.replace(/\s+/g, '_')}` : null,
    chironReport.shadowId ? `Shadow_${chironReport.shadowId}` : null,
  ].filter(Boolean),

  body_customFields: {
    // Replace with your actual GHL custom field ID
    czq4chc2frWMYtqzYxuH: JSON.stringify(chironReport),
  },
};

// ---- Output to next node ----
return [
  {
    json: {
      contactData,
      chironReport,
      rawWebhookBody: body,
    },
  },
];
